import{_ as a,o as r,c as t,a5 as n}from"./chunks/framework.bIR-4glx.js";const u=JSON.parse('{"title":"AI Trend Experiment: From Signal to Decision","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/ai-trend-radar.en.md","filePath":"public/downloads/worksheets/ai-trend-radar.en.md","lastUpdated":1795488252000}'),o={name:"public/downloads/worksheets/ai-trend-radar.en.md"};function i(d,e,s,l,c,p){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="ai-trend-experiment-from-signal-to-decision" tabindex="-1">AI Trend Experiment: From Signal to Decision <a class="header-anchor" href="#ai-trend-experiment-from-signal-to-decision" aria-label="Permalink to &quot;AI Trend Experiment: From Signal to Decision&quot;">​</a></h1><p>Test one change at a time. This is not a product scrapbook or a forecast leaderboard. It helps you decide whether a capability belongs in your task. Without a manual baseline, an inspectable result, and a stop condition, do not expand the scope.</p><h2 id="copyable-record" tabindex="-1">Copyable Record <a class="header-anchor" href="#copyable-record" aria-label="Permalink to &quot;Copyable Record&quot;">​</a></h2><h3 id="ai-trend-radar-yyyy-mm-dd" tabindex="-1">AI Trend Radar - YYYY-MM-DD <a class="header-anchor" href="#ai-trend-radar-yyyy-mm-dd" aria-label="Permalink to &quot;AI Trend Radar - YYYY-MM-DD&quot;">​</a></h3><h4 id="_1-signal-and-evidence" tabindex="-1">1. Signal and Evidence <a class="header-anchor" href="#_1-signal-and-evidence" aria-label="Permalink to &quot;1. Signal and Evidence&quot;">​</a></h4><p>Trend or capability:<br> Primary source, publication date/version, access date:<br> What the source actually observes:<br> My conditional judgment or future hypothesis:<br> Unknown, changeable, or unsupported by the source:</p><h4 id="_2-real-task" tabindex="-1">2. Real Task <a class="header-anchor" href="#_2-real-task" aria-label="Permalink to &quot;2. Real Task&quot;">​</a></h4><p>User, situation, and action to complete:<br> Current bottleneck:<br> Manual baseline location, time, and quality without the new capability:<br> Unsupported tasks or inputs:</p><h4 id="_3-smallest-experiment" tabindex="-1">3. Smallest Experiment <a class="header-anchor" href="#_3-smallest-experiment" aria-label="Permalink to &quot;3. Smallest Experiment&quot;">​</a></h4><p>The one thing changed this round:<br> Model, version, region, prompt, materials, memory, and tools:<br> Allowed input modes: text / audio / image / video / mixed<br> Data, copyright, privacy, and permission boundaries:<br> Allowed automation: read-only / draft / reversible action / irreversible action (approval required)<br> Normal, missing, conflicting, outdated, failure, and prompt-injection cases:<br> Development set / held-out set not used for tuning:</p><h4 id="_4-evidence-and-cost" tabindex="-1">4. Evidence and Cost <a class="header-anchor" href="#_4-evidence-and-cost" aria-label="Permalink to &quot;4. Evidence and Cost&quot;">​</a></h4><p>AI sample location:<br> Task/run IDs, trace, and checkpoint locations:<br> Clean environment, network egress allowlist, credential scope, and untrusted page/link-input note:<br> Tool calls, authorization, and final environment outcome:<br> Independent sample after closing AI:<br> Parallel task (changed topic/audience/mode/tool):<br> First-pass accepted / accepted after human repair:<br> Total time: preparation / run / checking / rework / maintenance:<br> Tool charges, device resources, and human-time valuation:<br> Source, recognition, factual, permission, and safety failures:</p><h4 id="_5-decision-and-exit" tabindex="-1">5. Decision and Exit <a class="header-anchor" href="#_5-decision-and-exit" aria-label="Permalink to &quot;5. Decision and Exit&quot;">​</a></h4><p>Did every hard gate pass? Evidence location:<br> Continue / downgrade / stop:<br> Permitted scope and human takeover conditions:<br> Retest trigger after model, material, tool, or memory changes:<br> Restorable version, disconnected-tool path, or manual fallback:<br> Supplier policy/version, effective date, region, and high-risk human review:<br> Independent reviewer, review method, and inspectable evidence location:<br> Can work continue after switching providers or sessions:<br> Owner and thirty-day review date:</p><h2 id="order-of-judgment" tabindex="-1">Order of Judgment <a class="header-anchor" href="#order-of-judgment" aria-label="Permalink to &quot;Order of Judgment&quot;">​</a></h2><p>Check sources and permissions first, then facts and task outcomes, and only then compare speed, style, or charges. Separate recognition errors from knowledge errors. Separate a model&#39;s completion claim from the file, database, or real reader outcome. Once a held-out set informs tuning, move it into development or regression coverage and add fresh held-out cases.</p><h2 id="related-entries" tabindex="-1">Related Entries <a class="header-anchor" href="#related-entries" aria-label="Permalink to &quot;Related Entries&quot;">​</a></h2><p><a href="https://byoungd.github.io/up/en/threads/part-3/6-ai-trends-and-learning-roadmap" target="_blank" rel="noreferrer">AI Trends and a Learning Roadmap</a> | <a href="https://byoungd.github.io/up/en/templates/ai-task-brief" target="_blank" rel="noreferrer">AI Task Brief</a> | <a href="https://byoungd.github.io/up/en/templates/ai-learning-log" target="_blank" rel="noreferrer">AI Learning Log</a> | <a href="https://byoungd.github.io/up/en/templates/ai-evaluation" target="_blank" rel="noreferrer">AI Evaluation Record</a></p><hr><p>Source: <a href="https://byoungd.github.io/up/en/templates/ai-trend-radar" target="_blank" rel="noreferrer">Still Here</a> · Manuscript updated: 2026-10-16. Content: <a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>.</p>',20)])])}const m=a(o,[["render",i]]);export{u as __pageData,m as default};
